-- Seed missing Revti Digital SOPs (published, with content), in the "SOP" category.
-- Safe to re-run: skips any title that already exists.

INSERT INTO document_categories (name, slug, color)
SELECT 'SOP', 'sop', '#0EA5E9'
WHERE NOT EXISTS (SELECT 1 FROM document_categories WHERE slug = 'sop');

WITH cat AS (SELECT id FROM document_categories WHERE slug = 'sop' LIMIT 1)
INSERT INTO documents (title, content, category_id, version, status)
SELECT v.title, v.content, (SELECT id FROM cat), '1.0', 'published'
FROM (VALUES
  ('SOP-002 – Client Onboarding Process', '<h1>SOP-002 – Client Onboarding Process</h1><h2>Purpose</h2><p>Standardize how a new client is set up, aligned, and prepared for delivery after a deal is closed.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Collect signed agreement, scope document, and initial payment confirmation.</li><li>Create the client record, project workspace, and shared communication channel.</li><li>Gather all required assets, credentials, and brand guidelines from the client.</li><li>Schedule and conduct the kickoff call to confirm scope, timeline, and points of contact.</li><li>Share the project plan and communication cadence, then move the project to active delivery.</li></ol><h2>Responsibilities</h2><ul><li><strong>Account Manager</strong></li><li><strong>Project Manager</strong></li><li><strong>Client</strong></li></ul>'),
  ('SOP-003 – Project Kickoff Process', '<h1>SOP-003 – Project Kickoff Process</h1><h2>Purpose</h2><p>Ensure every project starts with a clear scope, timeline, team, and success criteria.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Review the signed scope and prepare the internal project brief.</li><li>Assign the project team and define roles and responsibilities.</li><li>Break scope into milestones and build the delivery timeline.</li><li>Run the internal kickoff to align the team on goals and dependencies.</li><li>Set up the tracking board and confirm the first sprint deliverables.</li></ol><h2>Responsibilities</h2><ul><li><strong>Project Manager</strong></li><li><strong>Tech Lead</strong></li><li><strong>Account Manager</strong></li></ul>'),
  ('SOP-004 – Website Maintenance Process', '<h1>SOP-004 – Website Maintenance Process</h1><h2>Purpose</h2><p>Keep client websites secure, updated, and performing well through scheduled preventive checks.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Run scheduled health checks on uptime, backups, and core updates.</li><li>Update CMS, plugins, themes, and dependencies after testing on staging.</li><li>Review performance, security scans, and broken links.</li><li>Fix identified issues and document the changes made.</li><li>Share a maintenance report with the client for the cycle.</li></ol><h2>Responsibilities</h2><ul><li><strong>Maintenance Engineer</strong></li><li><strong>QA</strong></li><li><strong>Account Manager</strong></li></ul>'),
  ('SOP-005 – Website Launch Checklist Process', '<h1>SOP-005 – Website Launch Checklist Process</h1><h2>Purpose</h2><p>Provide a final verification checklist before any website goes live to production.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Confirm all content, pages, and forms are final and approved.</li><li>Verify SEO basics, analytics, redirects, and SSL are in place.</li><li>Test responsiveness, performance, and cross-browser behavior.</li><li>Take a full backup and prepare a rollback plan.</li><li>Deploy to production, run smoke tests, and confirm launch with the client.</li></ol><h2>Responsibilities</h2><ul><li><strong>Tech Lead</strong></li><li><strong>QA</strong></li><li><strong>Project Manager</strong></li></ul>'),
  ('SOP-006 – Bug Reporting & Issue Resolution Process', '<h1>SOP-006 – Bug Reporting & Issue Resolution Process</h1><h2>Purpose</h2><p>Define how bugs are reported, triaged, fixed, and verified consistently.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Log the bug with steps to reproduce, environment, and severity.</li><li>Triage and prioritize the issue and assign an owner.</li><li>Reproduce, diagnose the root cause, and implement the fix.</li><li>Test the fix on staging and get QA verification.</li><li>Deploy the fix and close the issue with a short resolution note.</li></ol><h2>Responsibilities</h2><ul><li><strong>Reporter</strong></li><li><strong>Developer</strong></li><li><strong>QA</strong></li></ul>'),
  ('SOP-007 – Change Request & Scope Management Process', '<h1>SOP-007 – Change Request & Scope Management Process</h1><h2>Purpose</h2><p>Control scope changes so timelines, cost, and expectations stay aligned.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Capture the change request with clear details and reason.</li><li>Assess impact on scope, timeline, and cost.</li><li>Share the impact and revised estimate with the client for approval.</li><li>Update the scope, plan, and tracking board once approved.</li><li>Implement the change and confirm delivery with the client.</li></ol><h2>Responsibilities</h2><ul><li><strong>Account Manager</strong></li><li><strong>Project Manager</strong></li><li><strong>Client</strong></li></ul>'),
  ('SOP-008 – Access & Credential Management Process', '<h1>SOP-008 – Access & Credential Management Process</h1><h2>Purpose</h2><p>Manage credentials and access securely across clients, servers, and tools.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Store all credentials only in the approved secure vault.</li><li>Grant access on a least-privilege, need-to-know basis.</li><li>Record who has access to what and why.</li><li>Rotate credentials periodically and after any suspected exposure.</li><li>Revoke access immediately when a project or role ends.</li></ol><h2>Responsibilities</h2><ul><li><strong>Admin</strong></li><li><strong>Team Lead</strong></li><li><strong>Security Owner</strong></li></ul>'),
  ('SOP-009 – Server & Infrastructure Management Process', '<h1>SOP-009 – Server & Infrastructure Management Process</h1><h2>Purpose</h2><p>Standardize provisioning, configuration, and monitoring of servers and infrastructure.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Provision servers using approved base configurations.</li><li>Harden security, firewalls, and access controls.</li><li>Set up monitoring, alerts, and log collection.</li><li>Apply patches and updates on a scheduled cadence.</li><li>Document the infrastructure setup and keep it current.</li></ol><h2>Responsibilities</h2><ul><li><strong>DevOps Engineer</strong></li><li><strong>Tech Lead</strong></li><li><strong>Admin</strong></li></ul>'),
  ('SOP-010 – Security & Incident Management Process', '<h1>SOP-010 – Security & Incident Management Process</h1><h2>Purpose</h2><p>Detect, respond to, and learn from security incidents in a structured way.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Monitor systems for security alerts and anomalies.</li><li>Classify the incident severity and notify stakeholders.</li><li>Contain the threat and preserve evidence.</li><li>Eradicate the cause and recover affected systems.</li><li>Run a post-incident review and apply preventive actions.</li></ol><h2>Responsibilities</h2><ul><li><strong>Security Owner</strong></li><li><strong>DevOps Engineer</strong></li><li><strong>Management</strong></li></ul>'),
  ('SOP-011 – Backup & Disaster Recovery Process', '<h1>SOP-011 – Backup & Disaster Recovery Process</h1><h2>Purpose</h2><p>Ensure data is backed up reliably and can be restored quickly after any failure.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Define backup scope, frequency, and retention per system.</li><li>Automate backups and verify they complete successfully.</li><li>Store backups securely in a separate location.</li><li>Test restores periodically to confirm recoverability.</li><li>Document the disaster recovery steps and recovery targets.</li></ol><h2>Responsibilities</h2><ul><li><strong>DevOps Engineer</strong></li><li><strong>Tech Lead</strong></li><li><strong>Admin</strong></li></ul>'),
  ('SOP-012 – Support Ticket Management Process', '<h1>SOP-012 – Support Ticket Management Process</h1><h2>Purpose</h2><p>Handle client support requests efficiently with clear priorities and SLAs.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Log every request as a ticket with category and priority.</li><li>Acknowledge the ticket within the defined response time.</li><li>Investigate, resolve, or escalate as needed.</li><li>Update the client with progress and resolution.</li><li>Close the ticket and capture any recurring patterns.</li></ol><h2>Responsibilities</h2><ul><li><strong>Support Engineer</strong></li><li><strong>Team Lead</strong></li><li><strong>Client</strong></li></ul>'),
  ('SOP-013 – Client Meeting & MOM Documentation Process', '<h1>SOP-013 – Client Meeting & MOM Documentation Process</h1><h2>Purpose</h2><p>Ensure client meetings are structured and decisions are documented and tracked.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Share an agenda before the meeting.</li><li>Conduct the meeting and note decisions and action items.</li><li>Circulate the minutes of meeting within the agreed time.</li><li>Add action items to the tracking board with owners and dates.</li><li>Follow up on pending items in the next meeting.</li></ol><h2>Responsibilities</h2><ul><li><strong>Project Manager</strong></li><li><strong>Account Manager</strong></li><li><strong>Client</strong></li></ul>'),
  ('SOP-014 – Project Closure & Handover Process', '<h1>SOP-014 – Project Closure & Handover Process</h1><h2>Purpose</h2><p>Close projects cleanly with complete handover and documentation.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Confirm all deliverables are complete and approved.</li><li>Hand over source code, credentials, and documentation.</li><li>Conduct a final walkthrough and training if required.</li><li>Collect client sign-off and feedback.</li><li>Archive project assets and record lessons learned.</li></ol><h2>Responsibilities</h2><ul><li><strong>Project Manager</strong></li><li><strong>Tech Lead</strong></li><li><strong>Client</strong></li></ul>'),
  ('SOP-015 – Employee Onboarding Process', '<h1>SOP-015 – Employee Onboarding Process</h1><h2>Purpose</h2><p>Give every new team member a smooth, consistent start.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Prepare accounts, hardware, and access before day one.</li><li>Share company policies, tools, and team structure.</li><li>Assign a buddy and initial ramp-up tasks.</li><li>Review role expectations and goals.</li><li>Check in at the end of the first week and first month.</li></ol><h2>Responsibilities</h2><ul><li><strong>HR</strong></li><li><strong>Reporting Manager</strong></li><li><strong>Admin</strong></li></ul>'),
  ('SOP-016 – Employee Exit & Access Removal Process', '<h1>SOP-016 – Employee Exit & Access Removal Process</h1><h2>Purpose</h2><p>Offboard team members securely with complete access removal.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Confirm the exit date and pending handovers.</li><li>Reassign responsibilities and knowledge transfer.</li><li>Revoke all system, tool, and credential access on the last day.</li><li>Collect company assets and settle final formalities.</li><li>Document the exit and update records.</li></ol><h2>Responsibilities</h2><ul><li><strong>HR</strong></li><li><strong>Reporting Manager</strong></li><li><strong>Admin</strong></li></ul>'),
  ('SOP-017 – Daily Task Update & Reporting Process', '<h1>SOP-017 – Daily Task Update & Reporting Process</h1><h2>Purpose</h2><p>Keep work visible and aligned through consistent daily updates.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Update task status on the tracking board each day.</li><li>Share progress, plans, and blockers in the daily standup.</li><li>Flag risks or delays early.</li><li>Keep time and effort logs accurate.</li><li>Escalate blockers that need help to the team lead.</li></ol><h2>Responsibilities</h2><ul><li><strong>Team Member</strong></li><li><strong>Team Lead</strong></li><li><strong>Project Manager</strong></li></ul>'),
  ('SOP-018 – Internal Knowledge Documentation Process', '<h1>SOP-018 – Internal Knowledge Documentation Process</h1><h2>Purpose</h2><p>Capture and maintain internal knowledge so it is reusable and current.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Identify processes and learnings worth documenting.</li><li>Write clear, structured documentation in the knowledge base.</li><li>Review documents for accuracy and clarity.</li><li>Publish and categorize for easy discovery.</li><li>Review and update documents periodically.</li></ol><h2>Responsibilities</h2><ul><li><strong>Author</strong></li><li><strong>Reviewer</strong></li><li><strong>Team Lead</strong></li></ul>'),
  ('SOP-019 – Git Repository Management Process', '<h1>SOP-019 – Git Repository Management Process</h1><h2>Purpose</h2><p>Standardize repository structure, branching, and access.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Create repositories using the approved structure and naming.</li><li>Follow the defined branching strategy for all work.</li><li>Protect main branches and require reviews to merge.</li><li>Manage access with least privilege.</li><li>Keep the repository clean, tagged, and documented.</li></ol><h2>Responsibilities</h2><ul><li><strong>Developer</strong></li><li><strong>Tech Lead</strong></li><li><strong>DevOps Engineer</strong></li></ul>'),
  ('SOP-020 – Code Review Process', '<h1>SOP-020 – Code Review Process</h1><h2>Purpose</h2><p>Ensure code quality, consistency, and knowledge sharing through reviews.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Open a pull request with a clear description and scope.</li><li>Assign reviewers and run automated checks.</li><li>Review for correctness, readability, and standards.</li><li>Address feedback and re-review as needed.</li><li>Approve and merge only when checks and reviews pass.</li></ol><h2>Responsibilities</h2><ul><li><strong>Author</strong></li><li><strong>Reviewer</strong></li><li><strong>Tech Lead</strong></li></ul>'),
  ('SOP-021 – API Development & Integration Process', '<h1>SOP-021 – API Development & Integration Process</h1><h2>Purpose</h2><p>Build and integrate APIs consistently, securely, and with proper documentation.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Define API requirements, contracts, and versioning.</li><li>Implement endpoints following security and error-handling standards.</li><li>Write tests and validate against the contract.</li><li>Document the API and share with consumers.</li><li>Monitor usage and handle deprecations carefully.</li></ol><h2>Responsibilities</h2><ul><li><strong>Developer</strong></li><li><strong>Tech Lead</strong></li><li><strong>QA</strong></li></ul>'),
  ('SOP-022 – Database Management Process', '<h1>SOP-022 – Database Management Process</h1><h2>Purpose</h2><p>Manage database design, changes, and health reliably.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Design schemas following normalization and naming standards.</li><li>Apply schema changes through reviewed migrations.</li><li>Back up data and verify integrity regularly.</li><li>Monitor performance and optimize queries and indexes.</li><li>Control access and audit sensitive data usage.</li></ol><h2>Responsibilities</h2><ul><li><strong>Developer</strong></li><li><strong>DevOps Engineer</strong></li><li><strong>Tech Lead</strong></li></ul>'),
  ('SOP-023 – Third Party Integration Process', '<h1>SOP-023 – Third Party Integration Process</h1><h2>Purpose</h2><p>Integrate external services safely and maintainably.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Evaluate the third party for fit, security, and reliability.</li><li>Review documentation, limits, and credentials handling.</li><li>Implement the integration with proper error handling.</li><li>Test edge cases and failure scenarios.</li><li>Document the integration and monitor it in production.</li></ol><h2>Responsibilities</h2><ul><li><strong>Developer</strong></li><li><strong>Tech Lead</strong></li><li><strong>QA</strong></li></ul>'),
  ('SOP-024 – Payment Gateway Integration Process', '<h1>SOP-024 – Payment Gateway Integration Process</h1><h2>Purpose</h2><p>Integrate payment gateways securely and compliantly.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Select the gateway and review compliance requirements.</li><li>Handle keys and secrets only through the secure vault.</li><li>Implement payment, refund, and webhook flows.</li><li>Test with sandbox and validate all transaction states.</li><li>Go live after security review and monitor transactions.</li></ol><h2>Responsibilities</h2><ul><li><strong>Developer</strong></li><li><strong>Tech Lead</strong></li><li><strong>Security Owner</strong></li></ul>'),
  ('SOP-025 – Software Product Release Management Process', '<h1>SOP-025 – Software Product Release Management Process</h1><h2>Purpose</h2><p>Plan and ship product releases in a controlled, repeatable way.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Define the release scope and freeze the code.</li><li>Run full regression testing and QA sign-off.</li><li>Prepare release notes and rollback plan.</li><li>Deploy following the release checklist.</li><li>Verify in production and communicate the release.</li></ol><h2>Responsibilities</h2><ul><li><strong>Release Manager</strong></li><li><strong>QA</strong></li><li><strong>Tech Lead</strong></li></ul>'),
  ('SOP-026 – Emergency Production Issue Handling Process', '<h1>SOP-026 – Emergency Production Issue Handling Process</h1><h2>Purpose</h2><p>Respond to critical production issues quickly to restore service.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Detect and confirm the production incident and its impact.</li><li>Assemble responders and communicate status.</li><li>Apply an immediate mitigation or rollback.</li><li>Implement and verify the permanent fix.</li><li>Run a post-mortem and add preventive measures.</li></ol><h2>Responsibilities</h2><ul><li><strong>On-call Engineer</strong></li><li><strong>Tech Lead</strong></li><li><strong>Management</strong></li></ul>'),
  ('SOP-027 – AI Usage & Implementation Process', '<h1>SOP-027 – AI Usage & Implementation Process</h1><h2>Purpose</h2><p>Govern how AI tools and models are used responsibly across work.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Use only approved AI tools and models for company work.</li><li>Never share confidential or client data with unapproved tools.</li><li>Validate AI outputs before using them in deliverables.</li><li>Document where and how AI was used.</li><li>Follow data privacy and compliance requirements.</li></ol><h2>Responsibilities</h2><ul><li><strong>Team Member</strong></li><li><strong>Tech Lead</strong></li><li><strong>Management</strong></li></ul>'),
  ('SOP-028 – AI Agent Development Process', '<h1>SOP-028 – AI Agent Development Process</h1><h2>Purpose</h2><p>Build AI agents in a structured, testable, and safe manner.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Define the agent goal, scope, tools, and guardrails.</li><li>Design the workflow, prompts, and integrations.</li><li>Implement with proper error handling and logging.</li><li>Test across scenarios including failure and edge cases.</li><li>Deploy, monitor behavior, and iterate.</li></ol><h2>Responsibilities</h2><ul><li><strong>AI Engineer</strong></li><li><strong>Tech Lead</strong></li><li><strong>QA</strong></li></ul>'),
  ('SOP-029 – AI Prompt Engineering Standard Process', '<h1>SOP-029 – AI Prompt Engineering Standard Process</h1><h2>Purpose</h2><p>Create consistent, effective, and maintainable prompts.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Define the task, context, and expected output format.</li><li>Draft prompts with clear instructions and examples.</li><li>Test prompts against varied inputs.</li><li>Refine for reliability, safety, and cost.</li><li>Version and document approved prompts.</li></ol><h2>Responsibilities</h2><ul><li><strong>AI Engineer</strong></li><li><strong>Reviewer</strong></li><li><strong>Tech Lead</strong></li></ul>'),
  ('SOP-030 – RAG Knowledge Base Management Process', '<h1>SOP-030 – RAG Knowledge Base Management Process</h1><h2>Purpose</h2><p>Manage the retrieval knowledge base for accurate AI responses.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Curate and clean source documents for the knowledge base.</li><li>Chunk, embed, and index content correctly.</li><li>Validate retrieval quality with test queries.</li><li>Update and re-index content as sources change.</li><li>Monitor answer quality and remove stale data.</li></ol><h2>Responsibilities</h2><ul><li><strong>AI Engineer</strong></li><li><strong>Content Owner</strong></li><li><strong>Tech Lead</strong></li></ul>'),
  ('SOP-031 – Technical Documentation Process', '<h1>SOP-031 – Technical Documentation Process</h1><h2>Purpose</h2><p>Produce clear, accurate technical documentation for systems and products.</p><h2>Scope</h2><p>This SOP applies to all relevant Revti Digital team members involved in this process.</p><h2>Procedure</h2><ol><li>Identify the audience and documentation scope.</li><li>Draft structured content with examples and diagrams.</li><li>Review for technical accuracy and clarity.</li><li>Publish in the agreed location and format.</li><li>Keep documentation updated with each change.</li></ol><h2>Responsibilities</h2><ul><li><strong>Author</strong></li><li><strong>Reviewer</strong></li><li><strong>Tech Lead</strong></li></ul>')
) AS v(title, content)
WHERE NOT EXISTS (SELECT 1 FROM documents d WHERE d.title = v.title);
